function historySnapshot(){return {caseGallery:clone(state.caseGallery),configs:clone(state.configs),templates:clone(state.templates),sourceCatalog:clone(state.sourceCatalog),costSource:clone(state.costSource),shopSettings:clone(state.shopSettings),active,activeShopId,selected:[...selected]};}
function syncHistoryButtons(){$('#undo').disabled=!history.length;$('#redo').disabled=!redoHistory.length;$('#poster-undo').disabled=!history.length;$('#poster-redo').disabled=!redoHistory.length;}
function checkpoint(){const snapshot=historySnapshot();if(JSON.stringify(history.at(-1))!==JSON.stringify(snapshot)){history.push(snapshot);const bytes=JSON.stringify(snapshot).length*2;while(history.length>1&&(history.length>30||history.length*bytes>32*1024*1024))history.shift();}syncHistoryButtons();}
function stepHistory(from,to,message){
 const snapshot=historySnapshot();let next=from.pop();while(next&&JSON.stringify(next)===JSON.stringify(snapshot))next=from.pop();if(!next){syncHistoryButtons();return;}
 to.push(snapshot);if(to.length>30)to.shift();
 state.caseGallery=next.caseGallery;state.configs=next.configs;state.templates=next.templates;state.sourceCatalog=next.sourceCatalog;state.costSource=next.costSource;state.shopSettings=next.shopSettings;activeShopId=next.activeShopId||'intel';localStorage.setItem('diy-active-shop',activeShopId);catalog=sourceCatalog(state.sourceCatalog||baseCatalog);state.costSource=costRows(catalog,state.costSource||[]);bindSources(state.configs,catalog);active=next.active;selected=new Set((next.selected||[]).filter(id=>available().some(c=>c.id===id)));posterEditor?.clear();
 restoringHistory=true;try{changed(message,state.configs.filter(c=>!c.deletedAt).map(c=>c.id));renderAll();}finally{restoringHistory=false;syncHistoryButtons();}
}
function changed(message='编辑配置',ids=[active],imageOnly=false){if(!imageOnly){if(!restoringHistory)syncDisplayEdits();else rememberDisplayParts();}if(!restoringHistory){redoHistory=[];syncHistoryButtons();}if(!imageOnly){for(const id of ids){const c=state.configs.find(x=>x.id===id);if(c&&message!=='新增配置链接'&&message!=='编辑商品链接')delete c.emptyLinkDraft;if(c?.shortNameAuto)c.shortName=suggestedName(c,c.nameFormat||'compact');}const nameInput=document.querySelector('[data-config=shortName]');if(nameInput&&document.activeElement!==nameInput)nameInput.value=current()?.shortName||'';}dirty=true;changeCounter++;changed.message=message;ids.forEach(id=>{pendingImages.add(id);imageRecords.delete(id);});$('#save-status').textContent='尚未保存';$('#image-status').textContent='预览已更新 · 停止操作后生成图片';$('#saved-image').classList.add('hidden');clearTimeout(timer);clearTimeout(imageTimer);if(!conflict)timer=setTimeout(()=>save().catch(()=>{}),950);if(!imageOnly){updateHeading();updateSummary();}if(imageOnly&&imageOnly!=='asset'&&previewResult?.redrawImages&&previewConfigId===active&&!previewBusy&&!previewFrame){(imageOnly==='layout'?previewResult.redrawLayout:previewResult.redrawImages)(current());paintPreview(previewResult);}else schedulePreview();}
function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const toBlob=canvas=>new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('图片生成失败')),'image/png'));
