function acceptSavedState(snapshot,remote){
 acceptedState=clone(remote);
 // Ordinary local receipts do not require rebasing every undo snapshot or rebuilding the UI.
 if(sameEditingState(snapshot,remote))return;
 for(const stack of [history,redoHistory]){const rebased=stack.map(item=>({item,result:mergeEditingState(snapshot,item,remote)}));if(rebased.some(x=>x.result.conflict))stack.length=0;else stack.splice(0,stack.length,...rebased.map(({item,result})=>({...result.state,active:item.active,activeShopId:item.activeShopId,selected:item.selected})));}
 syncHistoryButtons();const merged=mergeEditingState(snapshot,state,remote);state=merged.state;
 if(merged.conflict){conflict=true;dirty=true;openConflict('同步期间同一字段已变化，已保留你的输入，请先导出草稿并重新比较。');}
 catalog=sourceCatalog(state.sourceCatalog);if(!dirty)renderAll();
}
async function save(){
 if(conflict){openConflict('当前草稿尚未保存，请重新比较后选择保存版本。');throw Object.assign(Error('请在弹窗中处理保存冲突，当前输入已保留'),{status:409});}
 if(savePromise)return savePromise;
 if(!dirty)return;
 savePromise=(async()=>{try{while(dirty&&!conflict){
  const snapshot=clone(state);dirty=false;$('#save-status').textContent='正在保存到本机…';
  const data=await request('/api/state',{method:'POST',body:JSON.stringify({baseRevision:state.revision,baseState:acceptedState,caseGallery:snapshot.caseGallery,configs:snapshot.configs,templates:snapshot.templates,sourceCatalog:snapshot.sourceCatalog,costSource:snapshot.costSource,shopSettings:snapshot.shopSettings,operator,message:changed.message})});
  if(data.state)acceptSavedState(snapshot,data.state);else acceptedState=clone({...snapshot,revision:data.revision,updatedAt:data.updatedAt,logs:data.logs});state.revision=data.revision;state.updatedAt=data.updatedAt;state.logs=data.logs;$('#save-status').textContent=dirty?'尚未保存':`已保存 ${new Date(data.updatedAt).toLocaleTimeString('zh-CN')}`;
 }if(conflict)throw Object.assign(Error('同步期间同一字段已变化，请先处理保存冲突'),{status:409});scheduleImageSave();}catch(e){dirty=true;if(e.status===409){conflict=true;$('#save-status').textContent='保存冲突';openConflict(e.message);}else{$('#save-status').textContent='保存失败 · 请重试';toast(e.message);}throw e;}finally{savePromise=null;}})();return savePromise;
}
let imageTimer,imageJob=null;
function scheduleImageSave(){clearTimeout(imageTimer);if(pendingImages.size&&!conflict)imageTimer=setTimeout(()=>saveImages().catch(e=>console.warn(e.message)),3000);}
const blobBase64=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('图片编码失败'));reader.readAsDataURL(blob);});
async function saveImages(){
 clearTimeout(imageTimer);if(imageJob)return imageJob;if(dirty||savePromise||conflict)return;
 imageJob=(async()=>{for(const id of [...pendingImages]){
  if(dirty||savePromise||conflict)break;
  const source=state.configs.find(c=>c.id===id);if(!source||source.deletedAt){pendingImages.delete(id);continue;}
  const c=clone(source),count=changeCounter,revision=state.revision;
  try{
   const result=await renderPoster(c);if(result.overflow)throw Error('内容超出画布，请调整对象或恢复自动排版');
   const png=await blobBase64(await toBlob(result.canvas));
   if(dirty||count!==changeCounter||revision!==state.revision)break;
   const record=await request('/api/image',{method:'POST',body:JSON.stringify({id,revision,layout:c.layout,theme:c.theme,png})});
   if(!dirty&&count===changeCounter&&revision===state.revision){pendingImages.delete(id);imageRecords.set(id,record);if(id===active){$('#image-status').textContent=`图片已保存 · r${record.revision}`;$('#saved-image').href=record.url;$('#saved-image').classList.remove('hidden');}}
  }catch(e){if(id===active)$('#image-status').textContent='配置已保存在本机 · 图片待处理';if(e.status!==409)console.warn(e.message);}
 }} )();try{await imageJob;}finally{imageJob=null;}
}
function openConflict(message){openDialog('保存版本需要比较',`<p class="error">${esc(message)}</p><p class="hint">当前输入仍保留。可以重新比较并保存本页修改，或备份当前草稿后载入已保存版本。</p><div class="actions"><button id="conflict-backup">下载当前草稿</button><button id="conflict-compare" class="primary">重新比较</button><button id="conflict-reload">备份草稿并重新载入</button></div>`);$('#conflict-backup').onclick=backup;
 $('#conflict-reload').onclick=async()=>{try{await request('/api/recovery-draft',{method:'POST',body:JSON.stringify({state})});conflict=false;dirty=false;location.reload();}catch(e){toast(e.message);}};
 $('#conflict-compare').onclick=async()=>{try{const remote=await request('/api/state'),merged=mergeEditingState(acceptedState,state,remote);openDialog('选择保存版本',`<p class="hint">已读取最新保存版本。独立字段会自动合并；选择保留本页修改时，同一字段冲突以当前输入为准。</p><div class="actions"><button id="conflict-apply-local" class="primary">保留本页修改并保存</button><button id="conflict-cancel">返回编辑</button></div>`);$('#conflict-cancel').onclick=closeDialog;$('#conflict-apply-local').onclick=async()=>{try{await request('/api/recovery-draft',{method:'POST',body:JSON.stringify({state})});acceptedState=clone(remote);state=merged.state;conflict=false;dirty=true;closeDialog();await save();renderAll();}catch(e){toast(e.message);}};}catch(e){toast(e.message);}};
}
