 for(const [id,value] of [['excel-profit',t.taxProfit-p.fee],['erp-profit',t.erpProfit]]){const el=$('#'+id);el.textContent='¥'+money(value)+(id==='erp-profit'&&p.term>0?'（分期后实际 ¥'+money(t.erpProfit-p.fee)+'）':'');el.classList.toggle('loss',value<0);el.classList.toggle('gain',value>0);}
