 $('#duplicate').onclick=()=>{const capacityError=configCapacityMessage(state.configs,activeShopId,1);if(capacityError)return toast(capacityError);checkpoint();const c=clone(current());c.id=crypto.randomUUID();c.workspaceOrder=Math.max(-1,...state.configs.map((c,i)=>c.workspaceOrder??i))+1;c.name+=' · 副本';c.skuId='';state.configs.push(c);active=c.id;selected.add(c.id);changed('复制配置');renderAll();};
