$('#name-generate').onclick=()=>{checkpoint();current().shortNameAuto=true;current().nameFormat=$('#name-format').value;changed('生成简称');renderAll();};$('#ids').onclick=openIds;$('#link-parts').onclick=()=>openLinkParts({product:currentProduct(),openDialog,closeDialog,esc,toast,getConfigs:available,getSelectedIds:()=>chosen().map(c=>c.id),getCatalog:currentCatalog,apply:async plan=>{applyReplacement(plan,clone(available()));checkpoint();const ids=applyReplacement(plan,available());for(const id of ids){const c=state.configs.find(c=>c.id===id);displayBaseline.set(id,clone(c.parts));}changed(`${plan.scopeType==='selected'?'勾选配置':'链接内'}批量修改配件：${ids.length} 套配置`,ids);renderAll();await save();}});$('#batch-style').onclick=openBatchStyle;$('#global-batch-open').onclick=openGlobalParts;$('#inventory-check-open').onclick=openStockCheck;$('#inventory-export-open').onclick=()=>openInventoryExport({openDialog,esc,getConfigs:()=>state.configs,shop:currentShop(),download:downloadBlob,toast});
