try{[state,catalog,session]=await Promise.all([request('/api/state'),request('/catalog.json'),request('/api/session')]);operator=localStorage.getItem('diy-operator')||session.defaultOperator;acceptedState=clone(state);baseCatalog=catalog;state=normalizeWorkspaceState(state,baseCatalog);catalog=sourceCatalog(state.sourceCatalog);state.costSource=costRows(catalog,state.costSource||[]);bindSources(state.configs,catalog);normalizeProducts(state.configs);for(const c of state.configs){c.modules=posterModules(c);c.upgradeWeight??=400;}const remembered=localStorage.getItem('diy-active-shop');activeShopId=shops.some(shop=>shop.id===remembered)?remembered:'intel';active=available()[0]?.id||null;if(active)selected.add(active);bind();renderAll();installColorPicker({current,checkpoint});workspaceSyncUi=await bindWorkspaceSync({getState:()=>state,flush:save,openDialog,esc,toast,onMember:member=>{if(member){operator=member.name;$('#operator-open').textContent='成员：'+operator;$('#operator-open').disabled=false;$('#operator-open').title='账号管理：切换账号或退出登录';}else {$('#operator-open').textContent='请登录';$('#operator-open').disabled=false;}},receive:async()=>{if(dirty||savePromise||$('#dialog').open||document.activeElement?.matches('input,textarea,select'))return false;const counter=changeCounter;const next=await request('/api/state');if(counter!==changeCounter||dirty||savePromise)return false;if(next.revision===state.revision)return;state=normalizeWorkspaceState(next,baseCatalog);acceptedState=clone(next);catalog=sourceCatalog(state.sourceCatalog);bindSources(state.configs,catalog);normalizeProducts(state.configs);if(!current())active=available()[0]?.id||null;selected=new Set([...selected].filter(id=>available().some(c=>c.id===id)));history=[];redoHistory=[];imageRecords.clear();syncHistoryButtons();renderAll();}});$('#save-status').textContent=state.updatedAt?'已载入本地保存':'真实表格样例 · 尚未修改';}catch(e){$('#save-status').textContent=e.status===404?'需要重启工作台服务':'载入失败';if(e.status===404)$('#config-heading').textContent='请重启工作台以完成更新';$('#editor').innerHTML=`<p class="error">${esc(e.status===404?'工作台已更新，请双击 prototype 文件夹中的「重启原型.cmd」，然后刷新页面。':e.message)}</p>`;}

function updateSkuControls(){const c=current(),square=c?.layout==='square',padded=square&&c.skuMode==='padded';$('#sku-mode').classList.toggle('hidden',!square);$('#sku-mode').value=c?.skuMode||'dedicated';$('#sku-mode-hint').classList.toggle('hidden',!padded);$('#poster-auto-width').disabled=square;$('.canvas-tools').classList.toggle('hidden',padded);$('.preview-quick-actions').classList.toggle('hidden',square);}

function setPosterView(view){checkpoint();currentSettings().posterView=view;const ids=applyPosterView(available(),view);posterEditor?.clear();normalizePosterDesign(current());updateSkuControls();changed('统一本店配置图视图',ids,'asset');toast('本店全部配置已统一视图');}
